  KEY `idx_soundex_phrase` (`soundex`,`phrase`),
  KEY `idx_language` (`language`)
) ENGINE=InnoDB AUTO_INCREMENT=44215 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;/*ABDE:amn_finder_terms*/
DROP TABLE IF EXISTS `amn_redirect_links`;/*ABDE:amn_redirect_links*/
