DROP TABLE IF EXISTS `amn_messages_cfg`;/*ABDE:amn_messages_cfg*/
CREATE TABLE `amn_messages_cfg` (
  `user_id` int(10) unsigned NOT NULL DEFAULT 0,
  `cfg_name` varchar(100) NOT NULL DEFAULT '',
