DROP TABLE IF EXISTS `amn_akeebabackup_storage`;/*ABDE:amn_akeebabackup_storage*/
CREATE TABLE `amn_akeebabackup_storage` (
  `tag` varchar(255) NOT NULL,
  `lastupdate` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `data` longtext DEFAULT NULL,
  PRIMARY KEY (`tag`(100))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;/*ABDE:amn_akeebabackup_storage*/
DROP TABLE IF EXISTS `amn_phocagallery_img_votes`;/*ABDE:amn_phocagallery_img_votes*/
CREATE TABLE `amn_phocagallery_img_votes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `imgid` int(11) NOT NULL DEFAULT 0,
  `userid` int(11) NOT NULL DEFAULT 0,
