INSERT INTO `amn_content`  VALUES 
('251', '382', '1.B - ukázková průvodcovská praxe na náchodském zámku', '1-b-ukazkova-pruvodcovska-praxe-na-nachodskem-zamku', '<p class=\"MsoNormal\" style=\"margin-bottom: .0001pt; text-align: center; line-height: normal; mso-outline-level: 1;\" align=\"center\"> </p>\r\n<p style=\"text-align: center;\"><span style=\"text-decoration: underline;\"><span style=\"font-size: 14pt;\">1.B - ukázková průvodcovská praxe na náchodském zámku<br /></span></span></p>\r\n<p><span style=\"font-size: 14pt;\"><a href=\"images/foto/2023/ukazka_1.B.jpg\"><span style=\"text-decoration: underline;\"><img src=\"images/foto/2023/ukazka_1.B.jpg\" width=\"900\" /></span></a></span> </p>\r\n<p>Dne 30.9. jsme s třídou 1.B. obor cestovní ruch vyrazili  na naši první společnou prohlídku zámku. Začali jsme v Náchodě a myslím, že to stálo za to!! Zámeckou expozicí nás provedl student třetího ročníku Jirka Havel. Studenti se měli možnost dozvědět řadu zajímavostí z historie zámku a to především z období, kdy Náchodský zámek patřil rodu Piccolomini.</p>', '', '1', '9', '2022-10-05 10:48:32', '140', '', '2022-10-05 19:46:10', '140', NULL, NULL, '2022-10-05 10:48:32', NULL, '{\"image_intro\":\"\",\"image_intro_alt\":\"\",\"float_intro\":\"\",\"image_intro_caption\":\"\",\"image_fulltext\":\"\",\"image_fulltext_alt\":\"\",\"float_fulltext\":\"\",\"image_fulltext_caption\":\"\"}', '{\"urla\":false,\"urlatext\":\"\",\"targeta\":\"\",\"urlb\":false,\"urlbtext\":\"\",\"targetb\":\"\",\"urlc\":false,\"urlctext\":\"\",\"targetc\":\"\"}', '{\"article_layout\":\"\",\"show_title\":\"\",\"link_titles\":\"\",\"show_tags\":\"\",\"show_intro\":\"\",\"info_block_position\":\"\",\"info_block_show_title\":\"\",\"show_category\":\"\",\"link_category\":\"\",\"show_parent_category\":\"\",\"link_parent_category\":\"\",\"show_associations\":\"\",\"show_author\":\"\",\"link_author\":\"\",\"show_create_date\":\"\",\"show_modify_date\":\"\",\"show_publish_date\":\"\",\"show_item_navigation\":\"\",\"show_hits\":\"\",\"show_noauth\":\"\",\"urls_position\":\"\",\"alternative_readmore\":\"\",\"article_page_title\":\"\",\"show_publishing_options\":\"\",\"show_article_options\":\"\",\"show_urls_images_backend\":\"\",\"show_urls_images_frontend\":\"\"}', '1', '9', '', '', '1', '0', '{\"robots\":\"\",\"author\":\"\",\"rights\":\"\"}', '0', '*', ''),
