('937', '1068', 'Hana Dvorská česká kaskadérka - beseda pro sportovní management', 'beseda-s-p-dvorskou', '<p class=\"MsoNormal\" style=\"margin-bottom: .0001pt; text-align: center; line-height: normal; mso-outline-level: 1;\" align=\"center\"> </p>\r\n<p style=\"text-align: center;\"><span style=\"text-decoration: underline;\"><span style=\"font-size: 14pt;\">Hana Dvorská česká kaskadérka - beseda pro sportovní management</span></span></p>\r\n<p><a href=\"images/foto/2026/Dvorska.jpg\"><img class=\"float-none\" style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"images/foto/2026/Dvorska.jpg\" width=\"900\" height=\"506\"></a></p>\r\n<p class=\"MsoNormal\"><span style=\"font-size: 14px; line-height: 107%; font-family: arial, helvetica, sans-serif;\">Dne 23.1.2026 nás ve škole navštívila žena, která je velmi energická, je nejstarší kaskadérkou na světě a držitelkou ceny Věry Čáslavské, paní Hana Dvorská. Povídala nám o své práci, o životě a životních mottech, která ji provázejí celý její život. Na závěr měli studenti možnost se ptát na věci, které je zajímaly. Moc děkuji paní Dvorské za s námi strávený čas, stálo to za to. Hanka po konci besedy šla jezdit na Rozkoš, protože každá příležitost musí být využita.</span></p>', '', '1', '9', '2026-01-30 12:28:35', '140', '', '2026-02-09 17:01:51', '140', NULL, NULL, '2026-01-30 12:28:35', NULL, '{\"image_intro\":\"\",\"image_intro_alt\":\"\",\"float_intro\":\"\",\"image_intro_caption\":\"\",\"image_fulltext\":\"\",\"image_fulltext_alt\":\"\",\"float_fulltext\":\"\",\"image_fulltext_caption\":\"\"}', '{\"urla\":\"\",\"urlatext\":\"\",\"targeta\":\"\",\"urlb\":\"\",\"urlbtext\":\"\",\"targetb\":\"\",\"urlc\":\"\",\"urlctext\":\"\",\"targetc\":\"\"}', '{\"article_layout\":\"\",\"show_title\":\"\",\"link_titles\":\"\",\"show_tags\":\"\",\"show_intro\":\"\",\"info_block_position\":\"\",\"info_block_show_title\":\"\",\"show_category\":\"\",\"link_category\":\"\",\"show_parent_category\":\"\",\"link_parent_category\":\"\",\"show_associations\":\"\",\"flags\":\"\",\"show_author\":\"\",\"link_author\":\"\",\"show_create_date\":\"\",\"show_modify_date\":\"\",\"show_publish_date\":\"\",\"show_item_navigation\":\"\",\"show_hits\":\"\",\"show_noauth\":\"\",\"urls_position\":\"\",\"alternative_readmore\":\"\",\"article_page_title\":\"\",\"show_publishing_options\":\"\",\"show_article_options\":\"\",\"show_urls_images_backend\":\"\",\"show_urls_images_frontend\":\"\"}', '1', '56', '', '', '1', '0', '{\"robots\":\"\",\"author\":\"\",\"rights\":\"\"}', '0', '*', ''),
