('283', 'com_content.article.274', '', '2026-09-10 22:12:39', '140', '3512', 'feb94c2add3d0b2b26cdea9118d4cb93ccbd95db', '{\"title\":\"Domov ml\\u00e1de\\u017ee\",\"alias\":\"cs-domov-mladeze\",\"note\":\"\",\"catid\":8,\"state\":1,\"created\":\"2015-12-19 11:58:55\",\"publish_up\":\"2015-12-19 11:58:55\",\"ordering\":62,\"metakey\":\"\",\"metadesc\":\"\",\"access\":1,\"language\":\"cs-CZ\",\"featured\":0,\"attribs\":\"{\\\"article_layout\\\":\\\"\\\",\\\"show_title\\\":\\\"\\\",\\\"link_titles\\\":\\\"\\\",\\\"show_tags\\\":\\\"\\\",\\\"show_intro\\\":\\\"\\\",\\\"info_block_position\\\":\\\"\\\",\\\"info_block_show_title\\\":\\\"\\\",\\\"show_category\\\":\\\"\\\",\\\"link_category\\\":\\\"\\\",\\\"show_parent_category\\\":\\\"\\\",\\\"link_parent_category\\\":\\\"\\\",\\\"show_associations\\\":\\\"\\\",\\\"flags\\\":\\\"\\\",\\\"show_author\\\":\\\"\\\",\\\"link_author\\\":\\\"\\\",\\\"show_create_date\\\":\\\"\\\",\\\"show_modify_date\\\":\\\"\\\",\\\"show_publish_date\\\":\\\"\\\",\\\"show_item_navigation\\\":\\\"\\\",\\\"show_hits\\\":\\\"\\\",\\\"show_noauth\\\":\\\"\\\",\\\"urls_position\\\":\\\"\\\",\\\"alternative_readmore\\\":\\\"\\\",\\\"article_page_title\\\":\\\"\\\",\\\"show_publishing_options\\\":\\\"\\\",\\\"show_article_options\\\":\\\"\\\",\\\"show_urls_images_backend\\\":\\\"\\\",\\\"show_urls_images_frontend\\\":\\\"\\\"}\",\"images\":\"{\\\"image_intro\\\":\\\"\\\",\\\"image_intro_alt\\\":\\\"\\\",\\\"float_intro\\\":\\\"\\\",\\\"image_intro_caption\\\":\\\"\\\",\\\"image_fulltext\\\":\\\"\\\",\\\"image_fulltext_alt\\\":\\\"\\\",\\\"float_fulltext\\\":\\\"\\\",\\\"image_fulltext_caption\\\":\\\"\\\"}\",\"urls\":\"{\\\"urla\\\":\\\"\\\",\\\"urlatext\\\":\\\"\\\",\\\"targeta\\\":\\\"\\\",\\\"urlb\\\":\\\"\\\",\\\"urlbtext\\\":\\\"\\\",\\\"targetb\\\":\\\"\\\",\\\"urlc\\\":\\\"\\\",\\\"urlctext\\\":\\\"\\\",\\\"targetc\\\":\\\"\\\"}\",\"metadata\":\"{\\\"robots\\\":\\\"\\\",\\\"author\\\":\\\"\\\",\\\"rights\\\":\\\"\\\"}\",\"introtext\":\"<p><strong>Ubytov\\u00e1n\\u00ed<\\/strong><\\/p>\\r\\n<p><span style=\\\"font-size: 10pt;\\\">Domov ml\\u00e1de\\u017ee IV. (N\\u00e1chod, Raisova 678)<\\/span><br><span style=\\\"font-size: 10pt;\\\">DM IV. je po rekonstrukci ukon\\u010den\\u00e9 v\\u00a0roce 2006 ubytovac\\u00edm za\\u0159\\u00edzen\\u00edm I. kategorie. <\\/span><br><span style=\\\"font-size: 10pt;\\\">Cena l\\u016f\\u017eka pro \\u017e\\u00e1ky st\\u0159edn\\u00edch \\u0161kol v\\u00a0leto\\u0161n\\u00edm \\u0161koln\\u00edm roce (KHK) \\u010din\\u00ed K\\u010d 1500,00\\u00a0K\\u010d za m\\u011bs\\u00edc. <\\/span><br><span style=\\\"font-size: 10pt;\\\">Vratn\\u00e1 kauce \\u010din\\u00ed 1800,00\\u00a0K\\u010d (= n\\u00e1jem a\\u00a0z\\u00e1loha na kl\\u00ed\\u010de)<\\/span><\\/p>\\r\\n<p><span style=\\\"font-size: 10pt;\\\">Vedouc\\u00ed domov\\u016f ml\\u00e1de\\u017ee:<\\/span><br><span style=\\\"font-size: 10pt;\\\">V\\u00edtkov\\u00e1 Radmila<\\/span><br><span style=\\\"font-size: 10pt;\\\"> E-mail:\\u00a0<a href=\\\"mailto:vitkovaradmila@soanachod.cz\\\">vitkovaradmila@soanachod.cz<br><\\/a>mobil: +420\\u00a0602\\u00a0455\\u00a0050<\\/span><br><a href=\\\"https:\\/\\/www.soanachod.cz\\/domov-mladeze\\/informace\\/\\\"><span style=\\\"font-size: 10pt;\\\"><span style=\\\"font-family: tahoma, arial, helvetica, sans-serif;\\\"><span style=\\\"color: #255c97;\\\">http:\\/\\/<\\/span><\\/span><span style=\\\"font-family: tahoma, arial, helvetica, sans-serif;\\\"><span style=\\\"color: #255c97;\\\">soanachod.cz\\/domov-mladeze\\/<\\/span><\\/span><\\/span><\\/a><a href=\\\"https:\\/\\/www.soanachod.cz\\/domov-mladeze\\/informace\\/\\\" target=\\\"_blank\\\" rel=\\\"noopener\\\"><span style=\\\"font-size: 10pt;\\\"><span style=\\\"font-family: tahoma, arial, helvetica, sans-serif;\\\"><span style=\\\"color: #255c97;\\\">informace<\\/span><\\/span><\\/span><\\/a><span style=\\\"font-family: tahoma, arial, helvetica, sans-serif; font-size: 10pt;\\\"><br><a href=\\\"images\\/dokumenty\\/Ubytovani\\/Zdravotni_zpusobilost_v_DM.docx\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\"><br><\\/a><\\/span><\\/p>\\r\\n<p>\\u00a0<\\/p>\",\"tags\":{},\"typeAlias\":\"com_content.article\",\"id\":274,\"asset_id\":405,\"fulltext\":\"\",\"created_by\":140,\"created_by_alias\":\"\",\"publish_down\":null}', '0', '0', '0'),
