k; margin-left: auto; margin-right: auto;\\\" controls=\\\"controls\\\" width=\\\"900\\\" height=\\\"450\\\">\\r\\n<source src=\\\"images\\/video\\/praxe.mp4\\\" type=\\\"video\\/mp4\\\" \\/><\\/video><\\/p>\",\"tags\":{},\"typeAlias\":\"com_content.article\",\"id\":279,\"asset_id\":410,\"fulltext\":\"\",\"created_by\":140,\"created_by_alias\":\"\",\"publish_down\":null}', '0', '1', '0'),
