('499', 'com_content.article.490', '', '2026-09-10 22:15:03', '140', '2734', 'e086d6474fcc47f4d82e87ae62950806d93a4927', '{\"title\":\"Krajsk\\u00e9 kolo sout\\u011b\\u017ee v rusk\\u00e9m jazyce\",\"alias\":\"krajske-kolo-souteze-v-ruskem-jazyce\",\"note\":\"\",\"catid\":9,\"state\":1,\"created\":\"2017-03-20 09:10:52\",\"publish_up\":\"2017-03-20 09:10:52\",\"ordering\":337,\"metakey\":\"\",\"metadesc\":\"\",\"access\":1,\"language\":\"*\",\"featured\":0,\"attribs\":\"{\\\"article_layout\\\":\\\"\\\",\\\"show_title\\\":\\\"\\\",\\\"link_titles\\\":\\\"\\\",\\\"show_tags\\\":\\\"\\\",\\\"show_intro\\\":\\\"\\\",\\\"info_block_position\\\":\\\"\\\",\\\"show_category\\\":\\\"\\\",\\\"link_category\\\":\\\"\\\",\\\"show_parent_category\\\":\\\"\\\",\\\"link_parent_category\\\":\\\"\\\",\\\"show_author\\\":\\\"\\\",\\\"link_author\\\":\\\"\\\",\\\"show_create_date\\\":\\\"\\\",\\\"show_modify_date\\\":\\\"\\\",\\\"show_publish_date\\\":\\\"\\\",\\\"show_item_navigation\\\":\\\"\\\",\\\"show_hits\\\":\\\"\\\",\\\"show_noauth\\\":\\\"\\\",\\\"urls_position\\\":\\\"\\\",\\\"alternative_readmore\\\":\\\"\\\",\\\"show_publishing_options\\\":\\\"\\\",\\\"show_article_options\\\":\\\"\\\",\\\"show_urls_images_backend\\\":\\\"\\\",\\\"show_urls_images_frontend\\\":\\\"\\\"}\",\"images\":\"{\\\"image_intro\\\":\\\"\\\",\\\"image_intro_alt\\\":\\\"\\\",\\\"float_intro\\\":\\\"\\\",\\\"image_intro_caption\\\":\\\"\\\",\\\"image_fulltext\\\":\\\"\\\",\\\"image_fulltext_alt\\\":\\\"\\\",\\\"float_fulltext\\\":\\\"\\\",\\\"image_fulltext_caption\\\":\\\"\\\"}\",\"urls\":\"{\\\"urla\\\":false,\\\"urlatext\\\":\\\"\\\",\\\"targeta\\\":\\\"\\\",\\\"urlb\\\":false,\\\"urlbtext\\\":\\\"\\\",\\\"targetb\\\":\\\"\\\",\\\"urlc\\\":false,\\\"urlctext\\\":\\\"\\\",\\\"targetc\\\":\\\"\\\"}\",\"metadata\":\"{\\\"robots\\\":\\\"\\\",\\\"author\\\":\\\"\\\",\\\"rights\\\":\\\"\\\"}\",\"introtext\":\"<p class=\\\"MsoNormal\\\" style=\\\"margin-bottom: .0001pt; text-align: center; line-height: normal; mso-outline-level: 1;\\\" align=\\\"center\\\">\\u00a0<\\/p>\\r\\n<p style=\\\"text-align: center;\\\"><span style=\\\"text-decoration: underline;\\\"><span style=\\\"font-size: 14pt;\\\">Krajsk\\u00e9 kolo sout\\u011b\\u017ee v rusk\\u00e9m jazyce<br \\/><\\/span><\\/span><\\/p>\\r\\n<p style=\\\"text-align: left;\\\"><a href=\\\"images\\/foto\\/2017\\/souteze\\/Jazyky\\/Soumarova_soutez.jpg\\\" rel=\\\"alternate\\\"><span style=\\\"text-decoration: underline;\\\"><span style=\\\"font-size: 14pt;\\\"><img style=\\\"display: block; margin-left: auto; margin-right: auto;\\\" src=\\\"images\\/foto\\/2017\\/souteze\\/Jazyky\\/Soumarova_soutez.jpg\\\" alt=\\\"\\\" width=\\\"640\\\" \\/><\\/span><\\/span><\\/a><\\/p>\\r\\n<p>15. b\\u0159ezna 2017 se Dominika Soumarov\\u00e1, \\u017e\\u00e1kyn\\u011b 2. ro\\u010dn\\u00edku, z\\u00fa\\u010dastnila krajsk\\u00e9ho kola sout\\u011b\\u017ee v\\u00a0rusk\\u00e9m jazyce. V\\u00a0poslechov\\u00e9 \\u010d\\u00e1sti obsadila t\\u0159et\\u00ed m\\u00edsto. V\\u00a0celkov\\u00e9m sou\\u010dtu bod\\u016f se pot\\u00e9 um\\u00edstila na kr\\u00e1sn\\u00e9m dev\\u00e1t\\u00e9m m\\u00edst\\u011b. Dominice blahop\\u0159ejeme a d\\u011bkujeme za reprezentaci \\u0161koly.<\\/p>\\r\\n<p>\\u00a0<\\/p>\",\"tags\":{},\"typeAlias\":\"com_content.article\",\"id\":490,\"asset_id\":621,\"fulltext\":\"\",\"created_by\":140,\"created_by_alias\":\"\",\"publish_down\":null}', '0', '1', '0'),
('500', 'com_content.article.491', '', '2026-09-10 22:15:04', '140', '3124', '2ebcac0be3ddf678d08d87f940d77345b9f85cd5', '{\"title\":\"Veletrh v N\\u00e1chod\\u011b\",\"alias\":\"veletrh-v-nachode\",\"note\":\"\",\"catid\":9,\"state\":1,\"created\":\"2017-03-28 07:54:13\",\"publish_up\":\"2017-03-28 07:54:13\",\"ordering\":336,\"metakey\":\"\",\"metadesc\":\"\",\"access\":1,\"language\":\"*\",\"featured\":0,\"attribs\":\"{\\\"article_layout\\\":\\\"\\\",\\\"show_title\\\":\\\"\\\",\\\"link_titles\\\":\\\"\\\",\\\"show_tags\\\":\\\"\\\",\\\"show_intro\\\":\\\"\\\",\\\"info_block_position\\\":\\\"\\\",\\\"show_category\\\":\\\"\\\",\\\"link_category\\\":\\\"\\\",\\\"show_parent_category\\\":\\\"\\\",\\\"link_parent_category\\\":\\\"\\\",\\\"show_author\\\":\\\"\\\",\\\"link_author\\\":\\\"\\\",\\\"show_create_date\\\":\\\"\\\",\\\"show_modify_date\\\":\\\"\\\",\\\"show_publish_date\\\":\\\"\\\",\\\"show_item_navigation\\\":\\\"\\\",\\\"show_hits\\\":\\\"\\\",\\\"show_noauth\\\":\\\"\\\",\\\"urls_position\\\":\\\"\\\",\\\"alternative_readmore\\\":\\\"\\\",\\\"show_publishing_options\\\":\\\"\\\",\\\"show_article_options\\\":\\\"\\\",\\\"show_urls_images_backend\\\":\\\"\\\",\\\"show_urls_images_frontend\\\":\\\"\\\"}\",\"images\":\"{\\\"image_intro\\\":\\\"\\\",\\\"image_intro_alt\\\":\\\"\\\",\\\"float_intro\\\":\\\"\\\",\\\"image_intro_caption\\\":\\\"\\\",\\\"image_fulltext\\\":\\\"\\\",\\\"image_fulltext_alt\\\":\\\"\\\",\\\"float_fulltext\\\":\\\"\\\",\\\"image_fulltext_caption\\\":\\\"\\\"}\",\"urls\":\"{\\\"urla\\\":false,\\\"urlatext\\\":\\\"\\\",\\\"targeta\\\":\\\"\\\",\\\"urlb\\\":false,\\\"urlbtext\\\":\\\"\\\",\\\"targetb\\\":\\\"\\\",\\\"urlc\\\":false,\\\"urlctext\\\":\\\"\\\",\\\"targetc\\\":\\\"\\\"}\",\"metadata\":\"{\\\"robots\\\":\\\"\\\",\\\"author\\\":\\\"\\\",\\\"rights\\\":\\\"\\\"}\",\"introtext\":\"<p class=\\\"MsoNormal\\\" style=\\\"margin-bottom: .0001pt; text-align: center; line-height: normal; mso-outline-level: 1;\\\" align=\\\"center\\\">\\u00a0<\\/p>\\r\\n<p style=\\\"text-align: center;\\\"><span style=\\\"text-decoration: underline;\\\"><span style=\\\"font-size: 14pt;\\\">Veletrh v N\\u00e1chod\\u011b<br \\/><\\/span><\\/span><\\/p>\\r\\n<p>Dne 15. 3. 2017 se konal veletrh fiktivn\\u00edch firem v\\u00a0N\\u00e1chod\\u011b. T\\u0159\\u00edda 3. A. se poprv\\u00e9 z\\u00fa\\u010dastnila se svou fiktivn\\u00ed firmou <strong>Poh\\u0159ebn\\u00ed \\u00fastav Rakvi\\u010dka s. r. o.<\\/strong> \\u00a0M\\u011bla mo\\u017enost svou firmu p\\u0159edstavit v\\u00a0\\u010desk\\u00e9m i anglick\\u00e9m jazyce na z\\u00e1klad\\u011b p\\u0159edem p\\u0159ipraven\\u00e9 prezentace.\\u00a0 \\u017d\\u00e1ci komunikovali s\\u00a0\\u010desk\\u00fdmi i zahrani\\u010dn\\u00edmi z\\u00e1kazn\\u00edky a uzav\\u00edrali obchody s ostatn\\u00edmi fiktivn\\u00edmi firmami na veletrhu.<\\/p>\\r\\n<p><a href=\\\"images\\/foto\\/2017\\/WP_20170315_13_04_00_Pro.jpg\\\" rel=\\\"alternate\\\"><img style=\\\"display: block; margin-left: auto; margin-right: auto;\\\" src=\\\"images\\/foto\\/2017\\/WP_20170315_13_04_00_Pro.jpg\\\" alt=\\\"\\\" width=\\\"640\\\" \\/><\\/a><\\/p>\\r\\n<p>Na konci veletrhu se vyhl\\u00e1silo po\\u0159ad\\u00ed fiktivn\\u00edch firem, kter\\u00e9 se posuzovalo podle spr\\u00e1vnosti doklad\\u016f, schopnosti komunikovat a \\u00farovn\\u011b p\\u0159\\u00edpravy. Z\\u00a019 z\\u00fa\\u010dastn\\u011bn\\u00fdch firem se <strong>Poh\\u0159ebn\\u00ed \\u00fastav Rakvi\\u010dka s. r. o.<\\/strong> um\\u00edstil na 17. m\\u00edst\\u011b.\\u00a0 V hodnocen\\u00ed tiskov\\u00fdch v\\u00fdstup\\u016f a designu katalogu se um\\u00edstil na 4. m\\u00edst\\u011b.<\\/p>\",\"tags\":{},\"typeAlias\":\"com_content.article\",\"id\":491,\"asset_id\":622,\"fulltext\":\"\",\"created_by\":140,\"created_by_alias\":\"\",\"publish_down\":null}', '0', '1', '0'),
('501', 'com_content.article.492', '', '2026-09-10 22:15:05', '140', '3142', 'f8a045a6413496239779bc956298085b00aed159', '{\"title\":\"Krajsk\\u00e9 kolo olympi\\u00e1dy z angli\\u010dtiny\",\"alias\":\"krajske-kolo-olympiady-z-anglictiny\",\"note\":\"\",\"catid\":9,\"state\":0,\"created\":\"2017-03-30 11:08:06\",\"publish_up\":\"2017-03-30 11:08:06\",\"ordering\":335,\"metakey\":\"\",\"metadesc\":\"\",\"access\":1,\"language\":\"*\",\"featured\":0,\"attribs\":\"{\\\"article_layout\\\":\\\"\\\",\\\"show_title\\\":\\\"\\\",\\\"link_titles\\\":\\\"\\\",\\\"show_tags\\\":\\\"\\\",\\\"show_intro\\\":\\\"\\\",\\\"info_block_position\\\":\\\"\\\",\\\"show_category\\\":\\\"\\\",\\\"link_category\\\":\\\"\\\",\\\"show_parent_category\\\":\\\"\\\",\\\"link_parent_category\\\":\\\"\\\",\\\"show_author\\\":\\\"\\\",\\\"link_author\\\":\\\"\\\",\\\"show_create_date\\\":\\\"\\\",\\\"show_modify_date\\\":\\\"\\\",\\\"show_publish_date\\\":\\\"\\\",\\\"show_item_navigation\\\":\\\"\\\",\\\"show_hits\\\":\\\"\\\",\\\"show_noauth\\\":\\\"\\\",\\\"urls_position\\\":\\\"\\\",\\\"alternative_readmore\\\":\\\"\\\",\\\"show_publishing_options\\\":\\\"\\\",\\\"show_article_options\\\":\\\"\\\",\\\"show_urls_images_backend\\\":\\\"\\\",\\\"show_urls_images_frontend\\\":\\\"\\\"}\",\"images\":\"{\\\"image_intro\\\":\\\"\\\",\\\"image_intro_alt\\\":\\\"\\\",\\\"float_intro\\\":\\\"\\\",\\\"image_intro_caption\\\":\\\"\\\",\\\"image_fulltext\\\":\\\"\\\",\\\"image_fulltext_alt\\\":\\\"\\\",\\\"float_fulltext\\\":\\\"\\\",\\\"image_fulltext_caption\\\":\\\"\\\"}\",\"urls\":\"{\\\"urla\\\":false,\\\"urlatext\\\":\\\"\\\",\\\"targeta\\\":\\\"\\\",\\\"urlb\\\":false,\\\"urlbtext\\\":\\\"\\\",\\\"targetb\\\":\\\"\\\",\\\"urlc\\\":false,\\\"urlctext\\\":\\\"\\\",\\\"targetc\\\":\\\"\\\"}\",\"metadata\":\"{\\\"robots\\\":\\\"\\\",\\\"author\\\":\\\"\\\",\\\"rights\\\":\\\"\\\"}\",\"introtext\":\"<p class=\\\"MsoNormal\\\" style=\\\"margin-bottom: .0001pt; text-align: center; line-height: normal; mso-outline-level: 1;\\\" align=\\\"center\\\">\\u00a0<\\/p>\\r\\n<p style=\\\"text-align: center;\\\"><span style=\\\"text-decoration: underline;\\\"><span style=\\\"font-size: 14pt;\\\">Krajsk\\u00e9 kolo olympi\\u00e1dy z angli\\u010dtiny<br \\/><\\/span><\\/span><\\/p>\\r\\n<p style=\\\"text-align: justify;\\\">\\u017d\\u00e1kyn\\u011b 3. ro\\u010dn\\u00edku oboru Cestovn\\u00ed ruch Tereza Bendix Beranov\\u00e1 reprezentovala na\\u0161\\u00ed \\u0161kolu v\\u00a0krajsk\\u00e9m kole olympi\\u00e1dy z\\u00a0angli\\u010dtiny, kter\\u00e9 se konalo v\\u00a021. b\\u0159ezna v Hradci Kr\\u00e1lov\\u00e9. 10 sout\\u011b\\u017e\\u00edc\\u00edch pom\\u011b\\u0159ilo sv\\u00e9 znalosti v\\u00a0r\\u00e1mci poslechu a \\u010dten\\u00ed s\\u00a0porozum\\u011bn\\u00edm a p\\u0159i konverzaci na vylosovan\\u00e9 t\\u00e9ma. V\\u00a0konkurenci dal\\u0161\\u00edch st\\u0159edn\\u00edch \\u0161kol Kr\\u00e1lovehradeck\\u00e9ho kraje skon\\u010dila na kr\\u00e1sn\\u00e9m 4. m\\u00edst\\u011b. Toto um\\u00edst\\u011bn\\u00ed je o to cenn\\u011bj\\u0161\\u00ed, \\u017ee v\\u00a0na prvn\\u00edch t\\u0159ech m\\u00edstech se um\\u00edstila gymn\\u00e1zia a na\\u0161e \\u0161kola zaznamenala v\\u00a0r\\u00e1mci odborn\\u00fdch \\u0161kol prvenstv\\u00ed. Na z\\u00e1klad\\u011b t\\u011bchto v\\u00fdsledk\\u016f se na\\u0161e \\u0161kola um\\u00edstila na \\u0161pici st\\u0159edn\\u00edch \\u0161kol N\\u00e1chodska.<\\/p>\\r\\n<p style=\\\"text-align: justify;\\\">Blahop\\u0159ejeme a d\\u011bkujeme za p\\u0159\\u00edkladnou reprezentaci \\u0161koly.<\\/p>\\r\\n<p style=\\\"text-align: justify;\\\">\\u00a0Mgr. Jan \\u0160najdr<br \\/>vyu\\u010duj\\u00edc\\u00ed ANJ<\\/p>\",\"tags\":{},\"typeAlias\":\"com_content.article\",\"id\":492,\"asset_id\":623,\"fulltext\":\"\",\"created_by\":140,\"created_by_alias\":\"\",\"publish_down\":null}', '0', '1', '0'),
('502', 'com_content.article.493', '', '2026-09-10 22:15:05', '140', '2683', 'befa77bae35f2a3ef489c1046b12f9ab554a5046', '{\"title\":\"Veletrh FF Praha \",\"alias\":\"veletrh-ff-praha\",\"note\":\"\",\"catid\":9,\"state\":1,\"created\":\"2017-04-03 08:10:44\",\"publish_up\":\"2017-04-03 08:10:44\",\"ordering\":334,\"metakey\":\"\",\"metadesc\":\"\",\"access\":1,\"language\":\"*\",\"featured\":0,\"attribs\":\"{\\\"article_layout\\\":\\\"\\\",\\\"show_title\\\":\\\"\\\",\\\"link_titles\\\":\\\"\\\",\\\"show_tags\\\":\\\"\\\",\\\"show_intro\\\":\\\"\\\",\\\"info_block_position\\\":\\\"\\\",\\\"show_category\\\":\\\"\\\",\\\"link_category\\\":\\\"\\\",\\\"show_parent_category\\\":\\\"\\\",\\\"link_parent_category\\\":\\\"\\\",\\\"show_author\\\":\\\"\\\",\\\"link_author\\\":\\\"\\\",\\\"show_create_date\\\":\\\"\\\",\\\"show_modify_date\\\":\\\"\\\",\\\"show_publish_date\\\":\\\"\\\",\\\"show_item_navigation\\\":\\\"\\\",\\\"show_hits\\\":\\\"\\\",\\\"show_noauth\\\":\\\"\\\",\\\"urls_position\\\":\\\"\\\",\\\"alternative_readmore\\\":\\\"\\\",\\\"show_publishing_options\\\":\\\"\\\",\\\"show_article_options\\\":\\\"\\\",\\\"show_urls_images_backend\\\":\\\"\\\",\\\"show_urls_images_frontend\\\":\\\"\\\"}\",\"images\":\"{\\\"image_intro\\\":\\\"\\\",\\\"image_intro_alt\\\":\\\"\\\",\\\"float_intro\\\":\\\"\\\",\\\"image_intro_caption\\\":\\\"\\\",\\\"image_fulltext\\\":\\\"\\\",\\\"image_fulltext_alt\\\":\\\"\\\",\\\"float_fulltext\\\":\\\"\\\",\\\"image_fulltext_caption\\\":\\\"\\\"}\",\"urls\":\"{\\\"urla\\\":false,\\\"urlatext\\\":\\\"\\\",\\\"targeta\\\":\\\"\\\",\\\"urlb\\\":false,\\\"urlbtext\\\":\\\"\\\",\\\"targetb\\\":\\\"\\\",\\\"urlc\\\":false,\\\"urlctext\\\":\\\"\\\",\\\"targetc\\\":\\\"\\\"}\",\"metadata\":\"{\\\"robots\\\":\\\"\\\",\\\"author\\\":\\\"\\\",\\\"rights\\\":\\\"\\\"}\",\"introtext\":\"<p class=\\\"MsoNormal\\\" style=\\\"margin-bottom: .0001pt; text-align: center; line-height: normal; mso-outline-level: 1;\\\" align=\\\"center\\\">\\u00a0<\\/p>\\r\\n<p style=\\\"text-align: center;\\\"><span style=\\\"text-decoration: underline;\\\"><span style=\\\"font-size: 14pt;\\\">Veletrh FF Praha <br \\/><\\/span><\\/span><\\/p>\\r\\n<p>Ve \\u010dtvrtek, dne 23. 3., jsme se jako Poh\\u0159ebn\\u00ed \\u00fastav Rakvi\\u010dka, s.r.o. jeli pod\\u00edvat na jeden z\\u00a0nejv\\u011bt\\u0161\\u00edch Evropsk\\u00fdch veletrh\\u016f fiktivn\\u00edch firem v Praze za \\u00fa\\u010delem uskute\\u010d\\u0148ov\\u00e1n\\u00ed obchod\\u016f, pozn\\u00e1n\\u00ed nov\\u00fdch zku\\u0161enost\\u00ed a zlep\\u0161en\\u00ed obchodn\\u00edch dovednost\\u00ed.<br \\/> <br \\/><a href=\\\"images\\/foto\\/2017\\/FF.jpg\\\" rel=\\\"alternate\\\"><img style=\\\"display: block; margin-left: auto; margin-right: auto;\\\" src=\\\"images\\/foto\\/2017\\/FF.jpg\\\" alt=\\\"\\\" width=\\\"640\\\" \\/><\\/a><br \\/>Na\\u0161\\u00ed prioritou bylo poznat obchodn\\u00ed praktiky ostatn\\u00edch firem, se kter\\u00fdmi jsme se setkali. Celkov\\u011b tam \\u00fa\\u010dinkovalo 142 fiktivn\\u00edch firem z\\u00a010 evropsk\\u00fdch zem\\u00ed, nap\\u0159. ze Slovenska, Rakouska, Belgie, Finska, Bulharska a mnoho dal\\u0161\\u00edch.<\\/p>\",\"tags\":{},\"typeAlias\":\"com_content.article\",\"id\":493,\"asset_id\":624,\"fulltext\":\"\",\"created_by\":140,\"created_by_alias\":\"\",\"publish_down\":null}', '0', '1', '0'),
('503', 'com_content.article.494', '', '2026-09-10 22:15:06', '140', '4469', '9d27396d7d28246453a1eb69b4312d73fb0bbca2', '{\"title\":\"Dopoledne mezi seniory\",\"alias\":\"studentska-firma-tour-guide-3-b-prednaska-domov-senioru\",\"note\":\"\",\"catid\":9,\"state\":1,\"created\":\"2017-04-11 08:35:08\",\"publish_up\":\"2017-04-11 08:35:08\",\"ordering\":333,\"metakey\":\"\",\"metadesc\":\"\",\"access\":1,\"language\":\"*\",\"featured\":0,\"attribs\":\"{\\\"article_layout\\\":\\\"\\\",\\\"show_title\\\":\\\"\\\",\\\"link_titles\\\":\\\"\\\",\\\"show_tags\\\":\\\"\\\",\\\"show_intro\\\":\\\"\\\",\\\"info_block_position\\\":\\\"\\\",\\\"show_category\\\":\\\"\\\",\\\"link_category\\\":\\\"\\\",\\\"show_parent_category\\\":\\\"\\\",\\\"link_parent_category\\\":\\\"\\\",\\\"show_author\\\":\\\"\\\",\\\"link_author\\\":\\\"\\\",\\\"show_create_date\\\":\\\"\\\",\\\"show_modify_date\\\":\\\"\\\",\\\"show_publish_date\\\":\\\"\\\",\\\"show_item_navigation\\\":\\\"\\\",\\\"show_hits\\\":\\\"\\\",\\\"show_noauth\\\":\\\"\\\",\\\"urls_position\\\":\\\"\\\",\\\"alternative_readmore\\\":\\\"\\\",\\\"show_publishing_options\\\":\\\"\\\",\\\"show_article_options\\\":\\\"\\\",\\\"show_urls_images_backend\\\":\\\"\\\",\\\"show_urls_images_frontend\\\":\\\"\\\"}\",\"images\":\"{\\\"image_intro\\\":\\\"\\\",\\\"image_intro_alt\\\":\\\"\\\",\\\"float_intro\\\":\\\"\\\",\\\"image_intro_caption\\\":\\\"\\\",\\\"image_fulltext\\\":\\\"\\\",\\\"image_fulltext_alt\\\":\\\"\\\",\\\"float_fulltext\\\":\\\"\\\",\\\"image_fulltext_caption\\\":\\\"\\\"}\",\"urls\":\"{\\\"urla\\\":false,\\\"urlatext\\\":\\\"\\\",\\\"targeta\\\":\\\"\\\",\\\"urlb\\\":false,\\\"urlbtext\\\":\\\"\\\",\\\"targetb\\\":\\\"\\\",\\\"urlc\\\":false,\\\"urlctext\\\":\\\"\\\",\\\"targetc\\\":\\\"\\\"}\",\"metadata\":\"{\\\"robots\\\":\\\"\\\",\\\"author\\\":\\\"\\\",\\\"rights\\\":\\\"\\\"}\",\"introtext\":\"<p class=\\\"MsoNormal\\\" style=\\\"margin-bottom: .0001pt; text-align: center; line-height: normal; mso-outline-level: 1;\\\" align=\\\"center\\\">\\u00a0<\\/p>\\r\\n<p style=\\\"text-align: center;\\\"><span style=\\\"text-decoration: underline;\\\"><span style=\\\"font-size: 14pt;\\\">Dopoledne mezi seniory<br \\/><\\/span><\\/span><\\/p>\\r\\n<p style=\\\"text-align: center;\\\"><a href=\\\"images\\/foto\\/2017\\/DSCN4578.jpg\\\" rel=\\\"alternate\\\"><img src=\\\"images\\/foto\\/2017\\/DSCN4578.jpg\\\" alt=\\\"\\\" width=\\\"640\\\" \\/><\\/a><\\/p>\\r\\n<p>I kdy\\u017e se na\\u0161e studentsk\\u00e1 spole\\u010dnost Tour Guide zab\\u00fdv\\u00e1 po\\u0159\\u00e1d\\u00e1n\\u00edm z\\u00e1jezd\\u016f za kulturou a pozn\\u00e1n\\u00edm, rozhodli jsme se uspo\\u0159\\u00e1dat pro seniory z\\u00a0Penzionu pro seniory \\u2013 Hotel Metuj v\\u00a0Nov\\u00e9m M\\u011bst\\u011b nad Metuj\\u00ed nev\\u0161edn\\u00ed dopoledne.<br \\/>Proto\\u017ee ve sv\\u00fdch prax\\u00edch na na\\u0161em oboru Cestovn\\u00edho ruchu prov\\u00e1z\\u00edme po hradech, z\\u00e1mc\\u00edch a pevnostech n\\u00e1v\\u0161t\\u011bvn\\u00edky, tak n\\u00e1s napadlo, n\\u011bco z\\u00a0t\\u011bchto prax\\u00ed uk\\u00e1zat t\\u011bm, kte\\u0159\\u00ed se na tato m\\u00edsta nedostanou.<br \\/>3. 2017 jsme tak uspo\\u0159\\u00e1dali p\\u0159edn\\u00e1\\u0161kov\\u00e9 dopoledne prov\\u00e1zen\\u00e9 prezentacemi obr\\u00e1zk\\u016f z\\u00a0t\\u011bchto m\\u00edst senior\\u016fm ze zm\\u00edn\\u011bn\\u00e9ho penzionu. Hovo\\u0159ili jsme o samotn\\u00e9m Nov\\u00e9m M\\u011bst\\u011b nad Metuj\\u00ed, d\\u00e1le o \\u010cesk\\u00e9 Skalici, o m\\u011bstu, se kter\\u00fdm je spojeno jm\\u00e9no spisovatelky Bo\\u017eeny N\\u011bmcov\\u00e9 i o n\\u00e1rodn\\u00ed p\\u0159\\u00edrodn\\u00ed rezervaci o Adr\\u0161pa\\u0161sk\\u00fdch skal\\u00e1ch.<br \\/>Tak\\u00e9 o nedalek\\u00e9m pevnostn\\u00edm m\\u011bst\\u011b Josefov\\u011b, co\\u017e bylo velmi poutav\\u00e9 a zaj\\u00edmav\\u00e9 vystoupen\\u00ed M\\u00ed\\u0161i Bro\\u017eov\\u00e9, kdy se dostala se sv\\u00fdm vypr\\u00e1v\\u011bn\\u00edm i do vzd\\u00e1len\\u00e9 historie tohoto m\\u011bsta.<br \\/>N\\u011bkte\\u0159\\u00ed z\\u00a0n\\u00e1s prov\\u00e1zeli i d\\u00e1le od na\\u0161eho regionu, tak\\u017ee obyvatel\\u00e9 Penzionu pro seniory sly\\u0161eli i o romantick\\u00e9m hradu Bouzov, o z\\u00e1mku\\u00a0Buchlovice a o Lednick\\u00e9m z\\u00e1mku, kter\\u00fd pat\\u0159\\u00ed mezi nejkr\\u00e1sn\\u011bj\\u0161\\u00ed komplexy v\\u00a0\\u010cesk\\u00e9 republice.<br \\/>Dopoledne jsme zakon\\u010dili mal\\u00fdm kv\\u00edzem, co\\u017e bylo i rozpt\\u00fdlen\\u00edm pro seniory.<br \\/>Ti od druh\\u00e9 studentsk\\u00e9 spole\\u010dnosti na na\\u0161\\u00ed \\u0161kole KEP Trading company obdr\\u017eeli n\\u00e1st\\u011bnn\\u00e9 kalend\\u00e1\\u0159e, kter\\u00e9 studentsk\\u00e1 spole\\u010dnost sama navrhla a nechala vyrobit. Tento jejich dar byl velmi p\\u0159\\u00edhodn\\u00fd, nebo\\u0165 kalend\\u00e1\\u0159 obsahuje fotky historick\\u00fdch pam\\u00e1tek. Bylo to p\\u011bkn\\u00e9 zakon\\u010den\\u00ed cel\\u00e9 na\\u0161\\u00ed spole\\u010densk\\u00e9 akce v\\u00a0Pensionu pro seniory.<\\/p>\\r\\n<p>\\u00a0<\\/p>\",\"tags\":{},\"typeAlias\":\"com_content.article\",\"id\":494,\"asset_id\":625,\"fulltext\":\"\",\"created_by\":140,\"created_by_alias\":\"\",\"publish_down\":null}', '0', '1', '0'),
('504', 'com_content.article.495', '', '2026-09-10 22:15:06', '140', '3708', '0d0d50607fd03e2dd7e939449a87847de6cce70e', '{\"title\":\"Vzd\\u011bl\\u00e1vac\\u00ed program RJ\",\"alias\":\"vzdelavaci-program-rj\",\"note\":\"\",\"catid\":9,\"state\":0,\"created\":\"2017-04-12 09:27:06\",\"publish_up\":\"2017-04-12 09:30:21\",\"ordering\":332,\"metakey\":\"\",\"metadesc\":\"\",\"access\":1,\"language\":\"*\",\"featured\":0,\"attribs\":\"{\\\"article_layout\\\":\\\"\\\",\\\"show_title\\\":\\\"\\\",\\\"link_titles\\\":\\\"\\\",\\\"show_tags\\\":\\\"\\\",\\\"show_intro\\\":\\\"\\\",\\\"info_block_position\\\":\\\"\\\",\\\"show_category\\\":\\\"\\\",\\\"link_category\\\":\\\"\\\",\\\"show_parent_category\\\":\\\"\\\",\\\"link_parent_category\\\":\\\"\\\",\\\"show_author\\\":\\\"\\\",\\\"link_author\\\":\\\"\\\",\\\"show_create_date\\\":\\\"\\\",\\\"show_modify_date\\\":\\\"\\\",\\\"show_publish_date\\\":\\\"\\\",\\\"show_item_navigation\\\":\\\"\\\",\\\"show_hits\\\":\\\"\\\",\\\"show_noauth\\\":\\\"\\\",\\\"urls_position\\\":\\\"\\\",\\\"alternative_readmore\\\":\\\"\\\",\\\"show_publishing_options\\\":\\\"\\\",\\\"show_article_options\\\":\\\"\\\",\\\"show_urls_images_backend\\\":\\\"\\\",\\\"show_urls_images_frontend\\\":\\\"\\\"}\",\"images\":\"{\\\"image_intro\\\":\\\"\\\",\\\"image_intro_alt\\\":\\\"\\\",\\\"float_intro\\\":\\\"\\\",\\\"image_intro_caption\\\":\\\"\\\",\\\"image_fulltext\\\":\\\"\\\",\\\"image_fulltext_alt\\\":\\\"\\\",\\\"float_fulltext\\\":\\\"\\\",\\\"image_fulltext_caption\\\":\\\"\\\"}\",\"urls\":\"{\\\"urla\\\":false,\\\"urlatext\\\":\\\"\\\",\\\"targeta\\\":\\\"\\\",\\\"urlb\\\":false,\\\"urlbtext\\\":\\\"\\\",\\\"targetb\\\":\\\"\\\",\\\"urlc\\\":false,\\\"urlctext\\\":\\\"\\\",\\\"targetc\\\":\\\"\\\"}\",\"metadata\":\"{\\\"robots\\\":\\\"\\\",\\\"author\\\":\\\"\\\",\\\"rights\\\":\\\"\\\"}\",\"introtext\":\"<p class=\\\"MsoNormal\\\" style=\\\"margin-bottom: .0001pt; text-align: center; line-height: normal; mso-outline-level: 1;\\\" align=\\\"center\\\">\\u00a0<\\/p>\\r\\n<p style=\\\"text-align: center;\\\"><span style=\\\"text-decoration: underline;\\\"><span style=\\\"font-size: 14pt;\\\">Vzd\\u011bl\\u00e1vac\\u00ed program RJ<br \\/><\\/span><\\/span><\\/p>\\r\\n<p style=\\\"text-align: center;\\\"><a href=\\\"images\\/phocagallery\\/2017\\/HK_RJ\\/DSC02651.jpg\\\" rel=\\\"alternate\\\"><img src=\\\"images\\/phocagallery\\/2017\\/HK_RJ\\/DSC02651.jpg\\\" alt=\\\"\\\" width=\\\"640\\\" \\/><\\/a><\\/p>\\r\\n<p style=\\\"text-align: right;\\\"><em><span style=\\\"text-decoration: underline;\\\"><a href=\\\"index.php\\/cs\\/cs-fotogalerie\\/2016-2017\\/category\\/38-vzdelavaci-program-rj\\\" target=\\\"_blank\\\" rel=\\\"alternate\\\">Fotogalerie ZDE:<\\/a><\\/span><\\/em><\\/p>\\r\\n<p>Dne 11. 4. 2017 se \\u017e\\u00e1ci 1. a\\u017e 3. ro\\u010dn\\u00edku, kte\\u0159\\u00ed se u\\u010d\\u00ed rusk\\u00fd jazyk, vydali do Hradce Kr\\u00e1lov\\u00e9, aby uk\\u00e1zali sv\\u00e9 znalosti v\\u00a0ter\\u00e9nu. Studenti Pedagogick\\u00e9 fakulty v\\u00a0Hradci kr\\u00e1lov\\u00e9 si spole\\u010dn\\u011b s\\u00a0jejich vyu\\u010duj\\u00edc\\u00edm,\\u00a0Mgr. Miroslavem P\\u016f\\u017eou, Ph. D.,\\u00a0 p\\u0159ipravili didaktickou proch\\u00e1zku po m\\u011bst\\u011b s\\u00a0r\\u016fzn\\u00fdmi \\u00fakoly.<br \\/>Po absolvov\\u00e1n\\u00ed v\\u0161ech stanovi\\u0161\\u0165 jsme se v\\u0161ichni p\\u0159em\\u00edstili do jedn\\u00e9 z\\u00a0u\\u010deben pedagogick\\u00e9 fakulty, kde jsme se z\\u00fa\\u010dastnili p\\u0159edn\\u00e1\\u0161ky o Rusku, kter\\u00e1 prob\\u011bhla, jak jinak ne\\u017e v\\u00a0rusk\\u00e9m jazyce. B\\u011bhem p\\u0159edn\\u00e1\\u0161ky n\\u00e1m studenti fakulty, kte\\u0159\\u00ed n\\u00e1m po celou dobu programu byli k\\u00a0ruce a pom\\u00e1hali n\\u00e1m, opravili na\\u0161e odpov\\u011bdi a vyhodnotili nejlep\\u0161\\u00ed \\u00fa\\u010dastn\\u00edky.<\\/p>\\r\\n<ol>\\r\\n<li>m\\u00edsto \\u2013 Vlasta Pi\\u017elov\\u00e1 a Jan Jand\\u00edk (3. ro\\u010dn\\u00edk)<\\/li>\\r\\n<li>m\\u00edsto \\u2013 Veronika Ka\\u0161parovsk\\u00e1 a Monika Cejnarov\\u00e1 (1. ro\\u010dn\\u00edk)<\\/li>\\r\\n<li>m\\u00edsto \\u2013 Dominika Soumarov\\u00e1 a Daniel Zeman (2. ro\\u010dn\\u00edk)<\\/li>\\r\\n<\\/ol>\\r\\n<p>Za \\u017e\\u00e1ky - Dominika Soumarov\\u00e1, 2.ro\\u010dn\\u00edk<\\/p>\",\"tags\":{},\"typeAlias\":\"com_content.article\",\"id\":495,\"asset_id\":626,\"fulltext\":\"\",\"created_by\":140,\"created_by_alias\":\"\",\"publish_down\":null}', '0', '1', '0'),
('505', 'com_content.article.496', '', '2026-09-10 22:15:07', '140', '4591', '3512c1b59f6c6054a5b3f3a33f877041859956c0', '{\"title\":\"V\\u00fdm\\u011bnn\\u00fd pobyt v Holandsku\",\"alias\":\"vymenny-pobyt-v-holandsku\",\"note\":\"\",\"catid\":9,\"state\":1,\"created\":\"2017-04-18 06:31:16\",\"publish_up\":\"2017-04-18 06:40:09\",\"ordering\":330,\"metakey\":\"\",\"metadesc\":\"\",\"access\":1,\"language\":\"*\",\"featured\":0,\"attribs\":\"{\\\"article_layout\\\":\\\"\\\",\\\"show_title\\\":\\\"\\\",\\\"link_titles\\\":\\\"\\\",\\\"show_tags\\\":\\\"\\\",\\\"show_intro\\\":\\\"\\\",\\\"info_block_position\\\":\\\"\\\",\\\"show_category\\\":\\\"\\\",\\\"link_category\\\":\\\"\\\",\\\"show_parent_category\\\":\\\"\\\",\\\"link_parent_category\\\":\\\"\\\",\\\"show_author\\\":\\\"\\\",\\\"link_author\\\":\\\"\\\",\\\"show_create_date\\\":\\\"\\\",\\\"show_modify_date\\\":\\\"\\\",\\\"show_publish_date\\\":\\\"\\\",\\\"show_item_navigation\\\":\\\"\\\",\\\"show_hits\\\":\\\"\\\",\\\"show_noauth\\\":\\\"\\\",\\\"urls_position\\\":\\\"\\\",\\\"alternative_readmore\\\":\\\"\\\",\\\"show_publishing_options\\\":\\\"\\\",\\\"show_article_options\\\":\\\"\\\",\\\"show_urls_images_backend\\\":\\\"\\\",\\\"show_urls_images_frontend\\\":\\\"\\\"}\",\"images\":\"{\\\"image_intro\\\":\\\"\\\",\\\"image_intro_alt\\\":\\\"\\\",\\\"float_intro\\\":\\\"\\\",\\\"image_intro_caption\\\":\\\"\\\",\\\"image_fulltext\\\":\\\"\\\",\\\"image_fulltext_alt\\\":\\\"\\\",\\\"float_fulltext\\\":\\\"\\\",\\\"image_fulltext_caption\\\":\\\"\\\"}\",\"urls\":\"{\\\"urla\\\":false,\\\"urlatext\\\":\\\"\\\",\\\"targeta\\\":\\\"\\\",\\\"urlb\\\":false,\\\"urlbtext\\\":\\\"\\\",\\\"targetb\\\":\\\"\\\",\\\"urlc\\\":false,\\\"urlctext\\\":\\\"\\\",\\\"targetc\\\":\\\"\\\"}\",\"metadata\":\"{\\\"robots\\\":\\\"\\\",\\\"author\\\":\\\"\\\",\\\"rights\\\":\\\"\\\"}\",\"introtext\":\"<p class=\\\"MsoNormal\\\" style=\\\"margin-bottom: .0001pt; text-align: center; line-height: normal; mso-outline-level: 1;\\\" align=\\\"center\\\">\\u00a0<\\/p>\\r\\n<p style=\\\"text-align: center;\\\"><span style=\\\"text-decoration: underline;\\\"><span style=\\\"font-size: 14pt;\\\">V\\u00fdm\\u011bnn\\u00fd pobyt v Holandsku<br \\/><\\/span><\\/span><\\/p>\\r\\n<p style=\\\"text-align: center;\\\"><a href=\\\"images\\/phocagallery\\/2017\\/Holansko_duben\\/P4060528.jpg\\\" rel=\\\"alternate\\\"><img src=\\\"images\\/phocagallery\\/2017\\/Holansko_duben\\/P4060528.jpg\\\" alt=\\\"\\\" width=\\\"640\\\" \\/><\\/a><\\/p>\\r\\n<p style=\\\"text-align: right;\\\"><em><span style=\\\"text-decoration: underline;\\\"><a href=\\\"index.php\\/cs\\/cs-fotogalerie\\/2016-2017\\/category\\/39-holandko-duben\\\" target=\\\"_blank\\\" rel=\\\"alternate\\\">Fotogalerie ZDE:<\\/a><\\/span><\\/em><\\/p>\\r\\n<p>Prvn\\u00ed dubnov\\u00fd t\\u00fdden skupina student\\u016f z Academia Mercurii odlet\\u011bla do Holandska nav\\u0161t\\u00edvit ve m\\u011bst\\u011b Oud-Beijerland sv\\u00e9 p\\u0159\\u00e1tele z\\u00a0holandsk\\u00e9ho bilingu\\u00e1ln\\u00edho gymn\\u00e1zia Willem van Oranje. Studenti m\\u011bli mo\\u017enost nejen roz\\u0161\\u00ed\\u0159it si sv\\u00e9 znalosti o Holandsku a jeho kultu\\u0159e v\\u00a0r\\u00e1mci pozn\\u00e1vac\\u00edch v\\u00fdlet\\u016f po m\\u011bstech Rotterdam a Amsterdam, ale p\\u0159edev\\u0161\\u00edm roz\\u0161\\u00ed\\u0159it si slovn\\u00ed z\\u00e1sobu b\\u011bhem v\\u00fduky n\\u011bkter\\u00fdch \\u0161koln\\u00edch p\\u0159edm\\u011bt\\u016f v\\u00a0angli\\u010dtin\\u011b, kter\\u00e1 je jazykem v\\u00fduky tohoto bilingu\\u00e1ln\\u00edho gymn\\u00e1zia. Zaj\\u00edmav\\u00e1 byla v\\u00fduka fyziky, matematiky \\u010di zem\\u011bpisu a nov\\u00e9 z\\u00e1\\u017eitky jsme z\\u00edskali i b\\u011bhem hodin um\\u011bn\\u00ed \\u010di t\\u011blocviku. Studenti byli p\\u0159iv\\u00edt\\u00e1ni radn\\u00edm m\\u011bsta Oud-Beijerland a pot\\u00e9 si zahr\\u00e1li pozn\\u00e1vac\\u00ed hru Scavenger-hunt. Spole\\u010dn\\u00fd program byl v\\u00a0odpoledn\\u00edch hodin\\u00e1ch vyst\\u0159\\u00edd\\u00e1n programem, kte\\u0159\\u00ed studenti sd\\u00edleli se sv\\u00fdmi holandsk\\u00fdmi p\\u0159\\u00e1teli, v\\u00a0jejich\\u017e rodin\\u00e1ch byli t\\u011bchto 5 dn\\u00ed ubytov\\u00e1ni a vzniklo tak nejedno p\\u0159\\u00e1telstv\\u00ed, kter\\u00e9 bude pokra\\u010dovat vz\\u00e1jemn\\u00fdmi n\\u00e1v\\u0161t\\u011bvami o letn\\u00edch pr\\u00e1zdnin\\u00e1ch. A co bylo na na\\u0161em v\\u00fdletu nejp\\u0159ekvapiv\\u011bj\\u0161\\u00ed? Holandsko n\\u00e1m v\\u016fbec neuk\\u00e1zalo svou de\\u0161tivou tv\\u00e1\\u0159, a tak jsme m\\u011bli mo\\u017enost proch\\u00e1zet se (nebo se proj\\u00ed\\u017ed\\u011bt na kole, co\\u017e je v\\u00a0Oud-Beijerland b\\u011b\\u017en\\u011bj\\u0161\\u00ed ne\\u017e ch\\u016fze) mezi vodn\\u00edmi kan\\u00e1ly pln\\u00fdmi vodn\\u00edho ptactva za slune\\u010dn\\u00e9ho po\\u010das\\u00ed! A nyn\\u00ed se u\\u017e m\\u016f\\u017eeme t\\u011b\\u0161it, a\\u017e v\\u00a0z\\u00e1\\u0159\\u00ed op\\u011bt p\\u0159ijedou nov\\u00ed studenti tohoto holandsk\\u00e9ho gymn\\u00e1zia na v\\u00fdm\\u011bnn\\u00fd pobyt k\\u00a0n\\u00e1m do N\\u00e1choda a budou nav\\u00e1z\\u00e1na nov\\u00e1 p\\u0159\\u00e1telstv\\u00ed s\\u00a0na\\u0161imi studenty.<\\/p>\",\"tags\":{},\"typeAlias\":\"com_content.article\",\"id\":496,\"asset_id\":627,\"fulltext\":\"\",\"created_by\":140,\"created_by_alias\":\"\",\"publish_down\":null}', '0', '1', '0'),
('506', 'com_content.article.497', '', '2026-09-10 22:15:07', '140', '2568', '2cb714bbcef49f886491dfada2800b8d065ba874', '{\"title\":\"3. m\\u00edsto v krajsk\\u00e9m kole celost\\u00e1tn\\u00ed sout\\u011b\\u017ee FINAN\\u010cN\\u00cd GRAMOTNOST\",\"alias\":\"3-misto-v-krajskem-kole-celostatni-souteze-financni-gramotnost\",\"note\":\"\",\"catid\":9,\"state\":0,\"created\":\"2017-04-28 10:29:46\",\"publish_up\":\"2017-04-28 10:29:46\",\"ordering\":331,\"metakey\":\"\",\"metadesc\":\"\",\"access\":1,\"language\":\"*\",\"featured\":0,\"attribs\":\"{\\\"article_layout\\\":\\\"\\\",\\\"show_title\\\":\\\"\\\",\\\"link_titles\\\":\\\"\\\",\\\"show_tags\\\":\\\"\\\",\\\"show_intro\\\":\\\"\\\",\\\"info_block_position\\\":\\\"\\\",\\\"show_category\\\":\\\"\\\",\\\"link_category\\\":\\\"\\\",\\\"show_parent_category\\\":\\\"\\\",\\\"link_parent_category\\\":\\\"\\\",\\\"show_author\\\":\\\"\\\",\\\"link_author\\\":\\\"\\\",\\\"show_create_date\\\":\\\"\\\",\\\"show_modify_date\\\":\\\"\\\",\\\"show_publish_date\\\":\\\"\\\",\\\"show_item_navigation\\\":\\\"\\\",\\\"show_hits\\\":\\\"\\\",\\\"show_noauth\\\":\\\"\\\",\\\"urls_position\\\":\\\"\\\",\\\"alternative_readmore\\\":\\\"\\\",\\\"show_publishing_options\\\":\\\"\\\",\\\"show_article_options\\\":\\\"\\\",\\\"show_urls_images_backend\\\":\\\"\\\",\\\"show_urls_images_frontend\\\":\\\"\\\"}\",\"images\":\"{\\\"image_intro\\\":\\\"\\\",\\\"image_intro_alt\\\":\\\"\\\",\\\"float_intro\\\":\\\"\\\",\\\"image_intro_caption\\\":\\\"\\\",\\\"image_fulltext\\\":\\\"\\\",\\\"image_fulltext_alt\\\":\\\"\\\",\\\"float_fulltext\\\":\\\"\\\",\\\"image_fulltext_caption\\\":\\\"\\\"}\",\"urls\":\"{\\\"urla\\\":false,\\\"urlatext\\\":\\\"\\\",\\\"targeta\\\":\\\"\\\",\\\"urlb\\\":false,\\\"urlbtext\\\":\\\"\\\",\\\"targetb\\\":\\\"\\\",\\\"urlc\\\":false,\\\"urlctext\\\":\\\"\\\",\\\"targetc\\\":\\\"\\\"}\",\"metadata\":\"{\\\"robots\\\":\\\"\\\",\\\"author\\\":\\\"\\\",\\\"rights\\\":\\\"\\\"}\",\"introtext\":\"<p class=\\\"MsoNormal\\\" style=\\\"margin-bottom: .0001pt; text-align: center; line-height: normal; mso-outline-level: 1;\\\" align=\\\"center\\\">\\u00a0<\\/p>\\r\\n<p style=\\\"text-align: center;\\\"><span style=\\\"text-decoration: underline;\\\"><span style=\\\"font-size: 14pt;\\\">3. m\\u00edsto v krajsk\\u00e9m kole celost\\u00e1tn\\u00ed sout\\u011b\\u017ee FINAN\\u010cN\\u00cd GRAMOTNOST<br \\/><\\/span><\\/span><\\/p>\\r\\n<p style=\\\"text-align: center;\\\"><a href=\\\"images\\/foto\\/2017\\/souteze\\/krajske_kolo_FG.jpg\\\" rel=\\\"alternate\\\"><img src=\\\"images\\/foto\\/2017\\/souteze\\/krajske_kolo_FG.jpg\\\" alt=\\\"\\\" width=\\\"640\\\" \\/><\\/a><\\/p>\\r\\n<p>Gratulujeme!!!!<\\/p>\\r\\n<p><strong>K\\u00e1ja Viktorov\\u00e1<\\/strong> z\\u00a01. B, <strong>Erika R\\u00fddlov\\u00e1<\\/strong> z\\u00a03. A a <strong>M\\u00ed\\u0161a Bro\\u017eov\\u00e1<\\/strong> z\\u00a03. B obsadily kr\\u00e1sn\\u00e9 3. m\\u00edsto \\u00a0v\\u00a0Kr\\u00e1lovehradeck\\u00e9m kraji celost\\u00e1tn\\u00ed sout\\u011b\\u017ee finan\\u010dn\\u00ed gramotnost.<\\/p>\",\"tags\":{},\"typeAlias\":\"com_content.article\",\"id\":497,\"asset_id\":628,\"fulltext\":\"\",\"created_by\":140,\"created_by_alias\":\"\",\"publish_down\":null}', '0', '1', '0'),
